"""Documentacao da 213a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, REF_JOGO, CARREIRA_PT, CARREIRA_EN

N = 213
R = [('pode_contratar_jogador', 'TRANSFER_MANAGER::can_sign_player', '0x8ced40', 'transfer_manager.cpp', 'thiscall', 'se o clube pode contratar o jogador pelas regras da nação, com o motivo da recusa e a segunda chance do clube humano no limite de estrangeiros', "whether the club may sign the player under the nation rules, with the refusal reason and the human club's second try on the foreign player limit"), ('trocas_oferecendo_o_jogador', 'TRANSFER_MANAGER::get_exchange_offers_for_player', '0x8c5e40', 'transfer_manager.cpp', 'thiscall', 'quantas ofertas abertas do clube oferecem o jogador na troca, com a lista dos índices se pedida', "how many of the club's open offers include the player in the exchange, listing their indices when asked"), ('noticias_nao_lidas', 'News::count_unread', '0x786fe0', 'news.cpp', 'thiscall', 'as notícias não lidas da caixa do técnico humano, no total ou de uma categoria', "the unread news in a human manager's inbox, in total or for one category"), ('gravar_marca_da_noticia', 'News::set_item_slot', '0x786d30', 'news.cpp', 'thiscall', 'grava um valor numa vaga da notícia da caixa do técnico humano e na cópia local dela', "writes a value into a slot of a news item in the human manager's inbox and into its local copy"), ('clube_de_tecnico_humano', 'news_club_has_human_manager', '0x7875e0', 'news.cpp', 'stdcall', 'se um humano dirige o clube, sem contar as férias', 'whether a human manager runs the club, ignoring holidays'), ('data_do_sorteio_da_rodada', 'cup_set_round_draw_date', '0x521e60', 'Cup.cpp', 'cdecl', 'grava a data do sorteio da rodada da copa: o dia do ano e o ano contado do ano-base', 'stores the cup round draw date: the day number and the year offset from the base year'), ('data_do_jogo_da_rodada', 'cup_set_round_match_date', '0x521eb0', 'Cup.cpp', 'cdecl', 'grava a data do jogo da rodada da copa, o horário e as marcas do mando', 'stores the cup round match date, its match time and the venue flags'), ('tirar_clube_dos_amistosos', 'Friendly::remove_club_from_ai_plans', '0x5c64e0', 'friendly.cpp', 'thiscall', 'tira o clube dos amistosos planejados pelo computador e das listas de amistosos', 'removes the club from the planned AI friendlies and from the friendly lists')]
ESCAPADAS = {  # nome: (explicação pt, explicação en)
    'tr_recusa': ('na carreira as regras de transferência não recusam nenhuma contratação perguntada sem a segunda chance (a5 = 0), então o caminho "recusado, sem segunda pergunta" não roda (nem no modo comparação)', 'in the career the transfer rules never refuse a signing asked without the second chance (a5 = 0), so the "refused, no second question" path does not run (not even in comparison mode)'),
}
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia sem a referencia'
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
M = (f"`mutacoes/leva{N}.py` ({tot}, pela carreira até 2002-06-01, confirmando no modo comparação as que escapam): {ac} acusadas. {lac_pt} "
     f"Jogo real comparando até 2002-01-01: 0 divergências ({REF_JOGO}). Carreiras Rust ×2 e original até 2002-06-01: {CARREIRA_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, by the career to 2002-06-01, confirming the escaped ones in comparison mode): {ac} caught. {lac_en} "
      f"Real game comparing to 2002-01-01: 0 divergences ({REF_JOGO}). Rust ×2 and original careers to 2002-06-01: {CARREIRA_EN}")
fazer(N, 527, 527 + len(R), 'a contratação pelas regras da nação e as trocas que oferecem o jogador; as notícias não lidas, a marca gravada na notícia da caixa e o clube de técnico humano; as datas do sorteio e do jogo da rodada da copa e o clube que sai dos amistosos planejados', 'the signing by the nation rules and the exchanges offering the player; the unread news, the slot written into the inbox news item and the human-managed club; the draw and match dates of the cup round and the club removed from the planned friendlies',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'a contratação pelas regras da nação e as trocas que oferecem o jogador; as notícias não lidas, a marca gravada na notícia da caixa e o clube de técnico humano; as datas do sorteio e do jogo da rodada da copa e o clube que sai dos amistosos planejados', 'the signing by the nation rules and the exchanges offering the player; the unread news, the slot written into the inbox news item and the human-managed club; the draw and match dates of the cup round and the club removed from the planned friendlies', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en)
